mapper.select:
SELECT grade_code, grade_name, base_salary, description, sort_no
FROM salary_grade
WHERE grade_code = #{gradeCode}

SELECT employee_id, allowance, bonus_ratio, updated_by, updated_at
FROM employee_salary
WHERE employee_id = #{employeeId}

mapper.update:
UPDATE employee_salary
SET allowance = #{allowance}, bonus_ratio = #{bonusRatio}, updated_by = #{updatedBy}
WHERE employee_id = #{employeeId}

mapper.select:
SELECT id, employee_id, month, base_salary, allowance, performance_bonus, red_packet, total, created_at
FROM salary_monthly
WHERE employee_id = #{employeeId} AND month = #{month}

SELECT id, employee_id, month, base_salary, allowance, performance_bonus, red_packet, total, created_at
FROM salary_monthly
WHERE month >= #{fromMonth}
  AND employee_id IN
#{id}
ORDER BY month
